using System.Reflection;
namespace LSE.AutoCADElectrical.CatalogTools;
public static class CatalogTransactionService{
 public static string Execute(AppSettings s,CatalogAddRequest q){string backupRoot=Path.Combine(Path.GetDirectoryName(s.CatalogPath)??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"LSE_Catalog_Backups");string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");string backup=Path.Combine(backupRoot,stamp);Directory.CreateDirectory(backup);string backupFile=Path.Combine(backup,Path.GetFileName(s.CatalogPath));File.Copy(s.CatalogPath,backupFile,true);var log=new List<string>{$"Started: {DateTime.Now:s}",$"Catalog: {s.CatalogPath}",$"Backup: {backupFile}",$"Record: {q.TableName} | {q.Manufacturer} | {q.Catalog} | USER1={q.User1}"};bool vault=false;
  try{var svc=new AccessCatalogService(s.CatalogPath);if(svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("That manufacturer/catalog number already exists in the selected family.");if(!string.IsNullOrWhiteSpace(s.CatalogVaultPath)){VaultCatalogService.Checkout(s);vault=true;log.Add("Vault checkout: PASS");}svc.AddRecord(q);if(!svc.Exists(q.TableName,q.Manufacturer,q.Catalog))throw new InvalidOperationException("Read-back verification failed after insert.");log.Add("Database insert/read-back: PASS");if(vault){VaultCatalogService.Checkin(s,"Add electrical catalog component "+q.Manufacturer+" "+q.Catalog);log.Add("Vault checkin: PASS");}log.Add("Status: SUCCESS");File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);return string.Join(Environment.NewLine,log);}
  catch(Exception ex){log.Add("ERROR: "+ex);try{File.Copy(backupFile,s.CatalogPath,true);log.Add("Local rollback: PASS");}catch(Exception rx){log.Add("Local rollback: FAILED "+rx.Message);}if(vault)try{VaultCatalogService.UndoCheckout(s);log.Add("Vault undo checkout: PASS");}catch(Exception vx){log.Add("Vault undo checkout: FAILED "+vx.Message);}File.WriteAllLines(Path.Combine(backup,"TransactionReport.txt"),log);throw new InvalidOperationException(string.Join(Environment.NewLine,log),ex);}
 }
}
public static class VaultCatalogService{
 static (dynamic Wsm,dynamic DocSvc,dynamic File,Assembly Ws,Assembly Vdf,Assembly Framework) Connect(AppSettings s){string exp=s.VaultExplorerPath;if(!Directory.Exists(exp))throw new DirectoryNotFoundException("Vault Explorer SDK folder not found: "+exp);var ws=Assembly.LoadFrom(Path.Combine(exp,"Autodesk.Connectivity.WebServices.dll"));var vdf=Assembly.LoadFrom(Path.Combine(exp,"Autodesk.DataManagement.Client.Framework.Vault.dll"));var fw=Assembly.LoadFrom(Path.Combine(exp,"Autodesk.DataManagement.Client.Framework.dll"));Type wsmT=ws.GetType("Autodesk.Connectivity.WebServicesTools.WebServiceManager")!,credT=ws.GetType("Autodesk.Connectivity.WebServicesTools.WinAuthCredentials")!;foreach(var m in wsmT.GetMethods(BindingFlags.Public|BindingFlags.Static).Where(x=>x.Name=="Initialize")){try{m.Invoke(null,m.GetParameters().Length==0?null:new object[]{false});}catch{}break;}object? identity=null;foreach(var m in wsmT.GetMethods(BindingFlags.Public|BindingFlags.Static).Where(x=>x.Name=="GetServerIdentities")){object? z=m.GetParameters().Length==1?m.Invoke(null,new object[]{"http://"+s.VaultServer}):m.Invoke(null,new object[]{"http://"+s.VaultServer,30000});if(z is Array a&&a.Length>0)identity=a.GetValue(0);else identity=z;break;}if(identity==null)throw new InvalidOperationException("Could not obtain Vault server identity.");dynamic creds=Activator.CreateInstance(credT,new object?[]{identity,s.VaultName,false,null})!;dynamic wsm=Activator.CreateInstance(wsmT,creds)!;dynamic doc=wsm.DocumentService;dynamic found=doc.FindLatestFilesByPaths(new string[]{s.CatalogVaultPath});dynamic? file=null;foreach(var f in found){file=f;break;}if(file==null)throw new FileNotFoundException("Catalog was not found in Vault: "+s.CatalogVaultPath);return(wsm,doc,file,ws,vdf,fw);}
 public static void Checkout(AppSettings s){var x=Connect(s);if(Convert.ToInt64(x.File.CkOutUserId)>0)throw new InvalidOperationException("Catalog is already checked out.");Type opt=x.Ws.GetType("Autodesk.Connectivity.WebServices.CheckoutFileOptions")!;object choice=Enum.GetValues(opt).GetValue(0)!;object? ticket=null;x.DocSvc.CheckoutFile(x.File.Id,choice,Environment.MachineName,s.CatalogPath,"LSE Catalog Administration",ticket);File.SetAttributes(s.CatalogPath,FileAttributes.Normal);}
 public static void Checkin(AppSettings s,string comment){var x=Connect(s);Type connT=x.Vdf.GetType("Autodesk.DataManagement.Client.Framework.Vault.Currency.Connections.Connection")!,authT=x.Vdf.GetType("Autodesk.DataManagement.Client.Framework.Vault.Currency.Connections.AuthenticationFlags")!,itT=x.Vdf.GetType("Autodesk.DataManagement.Client.Framework.Vault.Currency.Entities.FileIteration")!,pathT=x.Framework.GetType("Autodesk.DataManagement.Client.Framework.Currency.FilePathAbsolute")!;object auth=Enum.Parse(authT,"WindowsAuthentication");dynamic conn=Activator.CreateInstance(connT,x.Wsm,s.VaultName,0,s.VaultServer,auth)!;dynamic it=Activator.CreateInstance(itT,conn,x.File)!;dynamic path=Activator.CreateInstance(pathT,s.CatalogPath)!;Type cls=x.Ws.GetType("Autodesk.Connectivity.WebServices.FileClassification")!;conn.FileManager.CheckinFile(it,comment,false,null,null,false,null,Enum.Parse(cls,"None"),false,path);}
 public static void UndoCheckout(AppSettings s){var x=Connect(s);object docService=(object)x.DocSvc;MethodInfo[] methods=docService.GetType().GetMethods();foreach(MethodInfo m in methods.Where((MethodInfo z)=>z.Name.Contains("UndoCheckout",StringComparison.OrdinalIgnoreCase))){try{var p=m.GetParameters();if(p.Length==1){m.Invoke(docService,new object[]{x.File.MasterId});return;}if(p.Length==2){m.Invoke(docService,new object[]{x.File.MasterId,Environment.MachineName});return;}}catch{}}throw new MissingMethodException("No compatible UndoCheckout method was found.");}
}
